 "content": "def transform(grid):
    """Undo the gray mask by copying the corresponding reflected base pattern."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    # Each demonstration shows a large 6-shaped occluder over the same
    # underlying design. The base design is invariant under 180-degree
    # rotation; copy from the rotational counterpart when visible.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                rr, cc = h - 1 - r, w - 1 - c
                if grid[rr][cc] != 6:
                    out[r][c] = grid[rr][cc]
    # Remaining cells are symmetrically masked; infer from an adjacent
    # visible continuation along the same row/column.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 6:
