    out = [row[:] for row in grid]
    # In this task the covered 6-regions conceal a highly repetitive ARC
    # pattern. Recover each 6 from matching visible positions in neighboring
    # rows (the demonstrations show repeated adjacent row motifs).
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            vals = []
            for d in range(1, h):
                for rr in (r-d, r+d):
                    if 0 <= rr < h and grid[rr][c] != 6:
                        vals.append((d, grid[rr][c]))
                if vals:
                    break
            if vals:
                counts = {}
                for _, v in vals:
                    counts[v] = counts.get(v, 0) + 1
                out[r][c] = max(counts, key=counts.get)
    return out
