 "content": "def transform(grid):
    """Restore gray cells using the grid's main-diagonal symmetry."""
    h, w = len(grid), len(grid[0]) if grid else 0
    out = [row[:] for row in grid]
    # The unmasked content is symmetric across the main diagonal.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6 and c < h and r < w and grid[c][r] != 6:
                out[r][c] = grid[c][r]
    # Where a gray mask covers both symmetric positions, use the most common
    # visible neighboring value around the symmetric pair.
    unresolved = [(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == 6 and out[r][c] == 6]
    seen = set()
    for r, c in unresolved:
        if (r, c) in seen:
            continue
        pair = {(r, c), (c, r)}
        seen.update(pair)
        counts = {}
        for a, b in pair:
            for da, db in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                x, y = a + da, b + db
                if 0 <= x < h and 0 <= y < w and out[x][y] != 6:
                    v = out[x][y]
                    counts[v] = counts.get(v, 0) + 1
        value = min(counts, key=lambda v: (-counts[v], v)) if counts else 0
        for a, b in pair:
            if a < h and b < w and out[a][b] == 6:
                out[a][b] = value
    return out
